#include "http_server.hpp"
#include "cluster.hpp"
#include "scheduler.hpp"
#include "json_utils.hpp"
#include "storage.hpp"
#include <iostream>
#include <sstream>
#include <fstream>
#include <algorithm>
#include <mutex>
#include <thread>
#include <chrono>
#include <random>
#include <iomanip>
#include <ctime>
static std::string ns(NodeStatus s){return s==NodeStatus::Idle?"Idle":s==NodeStatus::Busy?"Busy":"Offline";}
static std::string js(JobStatus s){return s==JobStatus::Queued?"Queued":s==JobStatus::Running?"Running":s==JobStatus::Completed?"Completed":"Failed";}
static std::string pn(Priority p){switch(p){case Priority::Critical:return"Critical";case Priority::High:return"High";case Priority::Medium:return"Medium";default:return"Low";}}
static bool auth(const Node*n,const std::string&t){return n&&!n->workerToken.empty()&&n->workerToken==t;}
static std::string state(const Cluster&c,const Scheduler&s,const std::string&mode,const std::string&strategy){std::ostringstream o;o<<"{\"mode\":\""<<mode<<"\",\"strategy\":\""<<strategy<<"\",\"capacity\":4,\"nodes\":[";bool f=true;for(const auto&n:c.nodes()){if(!f)o<<",";f=false;o<<"{\"id\":\""<<jsonEscape(n.id)<<"\",\"name\":\""<<jsonEscape(n.name)<<"\",\"cpuCores\":"<<n.cpuCores<<",\"ramGB\":"<<n.ramGB<<",\"ramUsedGB\":"<<n.ramUsedGB<<",\"gpuMemoryGB\":"<<n.gpuMemoryGB<<",\"gpuUsedGB\":"<<n.gpuUsedGB<<",\"cpuUsedPct\":"<<n.cpuUsedPct<<",\"gpuModel\":\""<<jsonEscape(n.gpuModel)<<"\",\"status\":\""<<ns(n.status)<<"\",\"live\":"<<(n.live?"true":"false")<<",\"completedJobs\":"<<n.completedJobs<<"}";}o<<"],\"jobs\":[";f=true;for(const auto&j:s.jobs()){if(!f)o<<",";f=false;o<<"{\"id\":\""<<j.id<<"\",\"name\":\""<<jsonEscape(j.name)<<"\",\"type\":\""<<jsonEscape(j.type)<<"\",\"priority\":\""<<pn(j.priority)<<"\",\"cpuRequired\":"<<j.cpuRequired<<",\"ramRequiredGB\":"<<j.ramRequiredGB<<",\"gpuRequiredGB\":"<<j.gpuRequiredGB<<",\"workUnits\":"<<j.workUnits<<",\"status\":\""<<js(j.status)<<"\",\"assignedNode\":\""<<jsonEscape(j.assignedNode)<<"\",\"message\":\""<<jsonEscape(j.message)<<"\",\"result\":\""<<jsonEscape(j.result)<<"\",\"executionSeconds\":"<<j.executionSeconds<<"}";}Metrics m=s.metrics(c);o<<"],\"metrics\":{\"submitted\":"<<m.submitted<<",\"completed\":"<<m.completed<<",\"queued\":"<<m.queued<<",\"running\":"<<m.running<<",\"failed\":"<<m.failed<<",\"averageWaitingSeconds\":"<<m.averageWaitingSeconds<<",\"averageExecutionSeconds\":"<<m.averageExecutionSeconds<<",\"averageUtilizationPct\":"<<m.averageUtilizationPct<<",\"resourceWastagePct\":"<<m.resourceWastagePct<<"}}";return o.str();}
static std::string readFrontendFile(const std::string& filename) {
    std::vector<std::string> paths = {
        "frontend/" + filename,
        "./frontend/" + filename,
        "../frontend/" + filename,
        "../../frontend/" + filename
    };
    for (const auto& p : paths) {
        std::ifstream f(p, std::ios::binary);
        if (f.is_open()) {
            return std::string(std::istreambuf_iterator<char>(f), {});
        }
    }
    return "";
}
int main(int argc,char**argv){unsigned short port=8080;if(argc>1){try{int p=std::stoi(argv[1]);if(p<1||p>65535)throw 1;port=(unsigned short)p;}catch(...){std::cerr<<"Usage: distriopt_server [port]\n";return 2;}}
 Cluster c;Scheduler s;std::mutex mx;std::string mode="Manual",strategy="DistriOpt";HttpServer server;
 auto stateResponse=[&](){return HttpResponse{200,"application/json",state(c,s,mode,strategy)};};
 auto serveIndex = [](const HttpRequest&) {
     std::string html = readFrontendFile("index.html");
     if (html.empty()) return HttpResponse{404,"text/plain","Run from the DistriOpt folder or place frontend/ alongside the executable."};
     return HttpResponse{200,"text/html",html};
 };
 server.get("/", serveIndex);
 server.get("/index.html", serveIndex);
 server.get("/style.css",[](const HttpRequest&){return HttpResponse{200,"text/css",readFrontendFile("style.css")};});
 server.get("/app.js",[](const HttpRequest&){return HttpResponse{200,"application/javascript",readFrontendFile("app.js")};});
 server.get("/favicon.ico",[](const HttpRequest&){return HttpResponse{204,"image/x-icon",""};});
 server.get("/api/state",[&](const HttpRequest&){std::lock_guard<std::mutex>l(mx);return stateResponse();});
 server.post("/api/mode",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);auto m=getString(r.body,"mode","Manual");if(m!="Manual"&&m!="Live")return HttpResponse{400,"application/json","{\"error\":\"Mode must be Manual or Live\"}"};if(m!=mode&&!c.nodes().empty())return HttpResponse{409,"application/json","{\"error\":\"Reset the current cluster before switching modes, so virtual and physical nodes are not mixed.\"}"};mode=m;return stateResponse();});
 server.post("/api/nodes",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);if(mode!="Manual")return HttpResponse{409,"application/json","{\"error\":\"Switch to Manual mode to create virtual nodes\"}"};Node n;n.name=getString(r.body,"name","Virtual compute node");n.cpuCores=(int)getNumber(r.body,"cpuCores",4);n.ramGB=getNumber(r.body,"ramGB",8);n.gpuMemoryGB=getNumber(r.body,"gpuMemoryGB",0);n.gpuModel=getString(r.body,"gpuModel",n.gpuMemoryGB>0?"GPU":"None");std::string e;if(!c.addNode(n,e))return HttpResponse{409,"application/json","{\"error\":\""+jsonEscape(e)+"\"}"};saveSnapshot(c.nodes(),s.jobs());return stateResponse();});
 server.post("/api/nodes/remove",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);if(!c.removeNode(getString(r.body,"id")))return HttpResponse{404,"application/json","{\"error\":\"Node not found\"}"};return stateResponse();});
 server.post("/api/jobs",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);Job j;j.name=getString(r.body,"name","Workload");j.type=getString(r.body,"type","Matrix Computation");j.cpuRequired=(int)getNumber(r.body,"cpuRequired",1);j.ramRequiredGB=getNumber(r.body,"ramRequiredGB",1);j.gpuRequiredGB=getNumber(r.body,"gpuRequiredGB",0);j.estimatedSeconds=(int)getNumber(r.body,"estimatedSeconds",5);j.workUnits=(int)getNumber(r.body,"workUnits",10000);std::string p=getString(r.body,"priority","Medium");j.priority=p=="Critical"?Priority::Critical:p=="High"?Priority::High:p=="Low"?Priority::Low:Priority::Medium;if(j.cpuRequired<1||j.ramRequiredGB<=0||j.gpuRequiredGB<0||j.workUnits<100||j.workUnits>2000000||j.estimatedSeconds<1)return HttpResponse{400,"application/json","{\"error\":\"Invalid resource requirements or workload size (100–2,000,000)\"}"};s.submit(j);s.schedule(c,strategy,mode);saveSnapshot(c.nodes(),s.jobs());return stateResponse();});
 server.post("/api/strategy",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);auto v=getString(r.body,"strategy","DistriOpt");if(v!="DistriOpt"&&v!="FCFS"&&v!="Priority")return HttpResponse{400,"application/json","{\"error\":\"Unknown strategy\"}"};strategy=v;s.schedule(c,strategy,mode);return stateResponse();});
 server.post("/api/fail-node",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);auto id=getString(r.body,"id");Node*n=c.findNode(id);if(!n)return HttpResponse{404,"application/json","{\"error\":\"Node not found\"}"};if(n->live){s.recoverNode(id,c,strategy);}else{c.failNode(id);for(auto&j:s.jobs())if(j.assignedNode==id&&j.status==JobStatus::Completed){j.status=JobStatus::Queued;j.assignedNode.clear();j.message="Restarted after simulated node failure";}s.schedule(c,strategy,mode);}return stateResponse();});
 server.post("/api/reset",[&](const HttpRequest&){std::lock_guard<std::mutex>l(mx);c.reset();s.reset();mode="Manual";strategy="DistriOpt";saveSnapshot(c.nodes(),s.jobs());return stateResponse();});
 // Live worker registration. The agent supplies a random shared token; arbitrary commands are never accepted.
 server.post("/api/workers/register",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);if(mode=="Manual"&&!c.nodes().empty())return HttpResponse{409,"application/json","{\"error\":\"Reset the manual cluster and select Live mode before registering physical workers.\"}"};mode="Live";Node n;n.name=getString(r.body,"name","DistriOpt Worker");n.cpuCores=(int)getNumber(r.body,"cpuCores",1);n.ramGB=getNumber(r.body,"ramGB",1);n.gpuMemoryGB=getNumber(r.body,"gpuMemoryGB",0);n.gpuModel=getString(r.body,"gpuModel","Not detected");n.live=true;n.workerToken=getString(r.body,"token");n.lastHeartbeat=(std::int64_t)std::time(nullptr);if(n.workerToken.size()<16)return HttpResponse{400,"application/json","{\"error\":\"Worker token must be at least 16 characters\"}"};Node* existing=nullptr;for(auto&candidate:c.nodes())if(candidate.live&&candidate.name==n.name){existing=&candidate;break;}if(existing){for(auto&job:s.jobs())if(job.assignedNode==existing->id&&job.status==JobStatus::Running){job.status=JobStatus::Queued;job.assignedNode.clear();job.claimed=false;job.message="Requeued because the worker agent reconnected; workload will restart";}existing->cpuUsedPct=0;existing->ramUsedGB=0;existing->gpuUsedGB=0;existing->activeJob.clear();existing->claimed=false;existing->workerToken=n.workerToken;existing->cpuCores=n.cpuCores;existing->ramGB=n.ramGB;existing->gpuMemoryGB=n.gpuMemoryGB;existing->gpuModel=n.gpuModel;existing->lastHeartbeat=n.lastHeartbeat;existing->status=NodeStatus::Idle;}else{std::string e;if(!c.addNode(n,e))return HttpResponse{409,"application/json","{\"error\":\""+jsonEscape(e)+"\"}"};}s.schedule(c,strategy,"Live");const Node& registered=existing?*existing:c.nodes().back();std::ostringstream o;o<<"{\"workerId\":\""<<registered.id<<"\",\"message\":\"Worker registered\"}";return HttpResponse{200,"application/json",o.str()};});
 server.post("/api/workers/heartbeat",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);auto id=getString(r.body,"workerId"),token=getString(r.body,"token");Node*n=c.findNode(id);if(!auth(n,token))return HttpResponse{401,"application/json","{\"error\":\"Worker authentication failed\"}"};n->lastHeartbeat=(std::int64_t)std::time(nullptr);if(n->status==NodeStatus::Offline)n->status=NodeStatus::Idle;return HttpResponse{200,"application/json","{\"ok\":true}"};});
 server.post("/api/workers/claim",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);auto id=getString(r.body,"workerId"),token=getString(r.body,"token");Node*n=c.findNode(id);if(!auth(n,token))return HttpResponse{401,"application/json","{\"error\":\"Worker authentication failed\"}"};Job*j=s.nextForWorker(id);if(!j)return HttpResponse{200,"application/json","{\"job\":null}"};std::ostringstream o;o<<"{\"job\":{\"id\":\""<<j->id<<"\",\"type\":\""<<jsonEscape(j->type)<<"\",\"workUnits\":"<<j->workUnits<<",\"cpuRequired\":"<<j->cpuRequired<<"}}";return HttpResponse{200,"application/json",o.str()};});
 server.post("/api/workers/result",[&](const HttpRequest&r){std::lock_guard<std::mutex>l(mx);auto id=getString(r.body,"workerId"),token=getString(r.body,"token"),jid=getString(r.body,"jobId");Node*n=c.findNode(id);if(!auth(n,token))return HttpResponse{401,"application/json","{\"error\":\"Worker authentication failed\"}"};bool ok=getNumber(r.body,"success",0)>0;double sec=getNumber(r.body,"seconds",0);auto result=getString(r.body,"result");if(!s.completeRemote(jid,id,ok,result,sec,c))return HttpResponse{404,"application/json","{\"error\":\"Running job not found\"}"};s.schedule(c,strategy,"Live");saveSnapshot(c.nodes(),s.jobs());return stateResponse();});
 server.post("/api/demo",[&](const HttpRequest&){std::lock_guard<std::mutex>l(mx);c.reset();s.reset();mode="Manual";strategy="DistriOpt";std::string e;Node a;a.name="CPU Compute · 01";a.cpuCores=8;a.ramGB=16;a.gpuModel="Integrated graphics";c.addNode(a,e);Node b;b.name="GPU Workstation · 02";b.cpuCores=12;b.ramGB=32;b.gpuMemoryGB=6;b.gpuModel="NVIDIA RTX-class (simulated)";c.addNode(b,e);Node d;d.name="Balanced Node · 03";d.cpuCores=6;d.ramGB=12;d.gpuMemoryGB=4;d.gpuModel="Dedicated GPU (simulated)";c.addNode(d,e);Node q;q.name="Memory Node · 04";q.cpuCores=4;q.ramGB=24;q.gpuModel="CPU only";c.addNode(q,e);for(int i=0;i<12;i++){Job j;j.name=(i%3==0?"Inference batch ":i%3==1?"Matrix workload ":"Data pipeline ")+std::to_string(i+1);j.type=i%3==0?"AI Inference":i%3==1?"Matrix Computation":"Data Processing";j.cpuRequired=1+i%4;j.ramRequiredGB=1.0+(i%5)*.7;j.gpuRequiredGB=(i%3==0)?1.0:0;j.priority=(Priority)(1+i%4);j.workUnits=10000+i*1000;s.submit(j);}s.schedule(c,strategy,mode);saveSnapshot(c.nodes(),s.jobs());return stateResponse();});
 server.post("/api/benchmark",[&](const HttpRequest&){std::lock_guard<std::mutex>l(mx);if(c.nodes().empty())return HttpResponse{409,"application/json","{\"error\":\"Add nodes or load the demo cluster before benchmarking.\"}"};std::ostringstream out;out<<"{\"results\":[";std::vector<std::string>strategies={"FCFS","Priority","DistriOpt"};for(size_t k=0;k<strategies.size();++k){Cluster test;std::string e;for(const auto&n:c.nodes()){Node cp=n;cp.id.clear();cp.live=false;cp.status=NodeStatus::Idle;cp.ramUsedGB=cp.gpuUsedGB=cp.cpuUsedPct=0;test.addNode(cp,e);}Scheduler bench;for(int i=0;i<300;i++){Job j;j.name="Benchmark workload";j.cpuRequired=1+i%std::max(1,test.nodes()[i%test.nodes().size()].cpuCores);j.ramRequiredGB=.5+(i%4)*.5;j.gpuRequiredGB=(i%7==0)?0.5:0;j.priority=(Priority)(1+i%4);j.workUnits=1000;bench.submit(j);}auto start=std::chrono::steady_clock::now();bench.schedule(test,strategies[k],"Manual");double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();auto m=bench.metrics(test);if(k)out<<",";out<<"{\"strategy\":\""<<strategies[k]<<"\",\"elapsedMs\":"<<ms<<",\"completed\":"<<m.completed<<",\"queued\":"<<m.queued<<",\"averageUtilizationPct\":"<<m.averageUtilizationPct<<"}";}out<<"]}";return HttpResponse{200,"application/json",out.str()};});
 std::thread watchdog([&](){while(true){std::this_thread::sleep_for(std::chrono::seconds(3));std::lock_guard<std::mutex>l(mx);auto now=(std::int64_t)std::time(nullptr);for(auto&n:c.nodes())if(n.live&&n.status!=NodeStatus::Offline&&n.lastHeartbeat>0&&now-n.lastHeartbeat>15)s.recoverNode(n.id,c,strategy);}});watchdog.detach();
 std::cout<<"DistriOpt controller ready. Open http://localhost:"<<port<<"\nFor LAN workers, use this PC's local IPv4 address and port "<<port<<".\n"<<std::flush;return server.listen(port)?0:1;
}
